470	// drain waits, up to the deadline, for the requests in flight besides this one.
471	func (s *server) drain(deadline time.Duration) Reply {
472		before := s.inflight.Load() + s.busy() - 1
473		end := time.Now().Add(deadline)
474		for s.inflight.Load()+s.busy() > 1 && time.Now().Before(end) {
475			time.Sleep(5 * time.Millisecond)
476		}
477		left := s.inflight.Load() + s.busy() - 1
478		if left < 0 {
479			left = 0
480		}
481		if before < 0 {
482			before = 0
483		}
484		r := s.state(true)
485		r.Drained, r.Abandoned = before-left, left
486		return r
487	}
